dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "phenotype",
      "label": "Phenotype",
      "type": "list",
      "values": [
        {
          "label": "HEIGHT",
          "value": "HEIGHT_GIANT"
        },
        {
          "label": "BMI",
          "value": "BMI_GIANT"
        },
        {
          "label": "Waist-hip ratio adjusted BMI",
          "value": "WHRadjBMI_GIANT"
        },
        {
          "label": "Waist-Hip ration unadjusted",
          "value": "WHRU_GIANT"
        }
      ]
    },
    {
      "parameter": "region",
      "label": "Region by Gene (+-500K) ",
      "type": "input",
      "values": "kp genes",
      "convert to region": "true",
      "expand region by": 1000000
    },
    {
      "parameter": "sex",
      "label": "Sex",
      "type": "list",
      "values": [
        {
          "label": "Mixed",
          "value": "mixed"
        },
        {
          "label": "Male",
          "value": "male"
        },
        {
          "label": "Female",
          "value": "female"
        }
      ]
    },
    {
      "parameter": "ancestry",
      "label": "Ancestry",
      "type": "list",
      "values": [
        {
          "label": "Mixed",
          "value": "Mixed"
        },
        {
          "label": "African American",
          "value": "AA"
        },
        {
          "label": "East Asian",
          "value": "EA"
        },
        {
          "label": "Hispanic",
          "value": "HS"
        },
        {
          "label": "South Asian",
          "value": "SA"
        },
        {
          "label": "Europian",
          "value": "EU"
        }
      ]
    }
  ],
  "sections": [
    {
      "section id": "associations",
      "header": "Associations",
      "data point": {
        "type": "bioindex",
        "url": "https://giant.hugeampkpnbi.org/api/bio/",
        "index": "associations",
        "parameters": [
          "ancestry",
          "sex",
          "phenotype",
          "region"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "chromosome",
            "raw field": "chromosome"
          },
          {
            "type": "raw",
            "field name": "Position",
            "raw field": "position"
          },
          {
            "type": "raw",
            "field name": "ref",
            "raw field": "reference"
          },
          {
            "type": "raw",
            "field name": "alt",
            "raw field": "alt"
          },
          {
            "type": "raw",
            "field name": "Ancestry",
            "raw field": "ancestry"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "beta"
          },
          {
            "type": "raw",
            "field name": "Odds Ratio",
            "raw field": "oddsRatio"
          },
          {
            "type": "raw",
            "field name": "EAF",
            "raw field": "eaf"
          },
          {
            "type": "raw",
            "field name": "MAF",
            "raw field": "maf"
          },
          {
            "type": "raw",
            "field name": "Standard Error",
            "raw field": "stdErr"
          },
          {
            "type": "raw",
            "field name": "Z Score",
            "raw field": "zScore"
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue"
          },
          {
            "type": "join",
            "field name": "Ref/Alt",
            "fields to join": [
              "reference",
              "alt"
            ],
            "join by": "/"
          },
          {
            "type": "join",
            "field name": "Locus",
            "fields to join": [
              "chromosome",
              "position"
            ],
            "join by": ":"
          },
          {
            "type": "join multi",
            "field name": "Variant ID",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              ":",
              "_",
              "/"
            ]
          },
          {
            "type": "raw",
            "field name": "chr",
            "raw field": "chromosome"
          },
          {
            "type": "raw",
            "field name": "Consequence",
            "raw field": "consequence"
          },
          {
            "type": "calculate",
            "field name": "-log10(P-Value)",
            "raw field": "pValue",
            "calculation type": "-log10"
          }
        ],
        "top rows": [
          "Variant ID",
          "Ref/Alt",
          "Ancestry",
          "P-Value",
          "Beta",
          "Odds Ratio",
          "EAF",
          "MAF",
          "Standard Error",
          "Z Score",
          "Consequence"
        ],
        "locus field": "Locus",
        "column formatting": {
          "P-Value": {
            "type": [
              "scientific notation"
            ]
          },
          "Odds Ratio": {
            "type": [
              "scientific notation"
            ]
          },
          "EAF": {
            "type": [
              "scientific notation"
            ]
          },
          "MAF": {
            "type": [
              "scientific notation"
            ]
          },
          "Standard Error": {
            "type": [
              "scientific notation"
            ]
          },
          "Z Score": {
            "type": [
              "scientific notation"
            ]
          }
        }
      },
      "pre filters": [
        {
          "field": "P-Value",
          "value": 0.05,
          "type": "search lower than"
        }
      ],
      "filters": [
        {
          "field": "Variant ID",
          "label": "Variant ID",
          "type": "search",
          "label in bubble": "true"
        },
        {
          "field": "P-Value",
          "label": "P-Value (<=)",
          "type": "search lower than",
          "label in bubble": "true"
        },
        {
          "field": "EAF",
          "label": "EAF (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Beta",
          "label": "Beta (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Z Score",
          "label": "Z Score (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Consequence",
          "label": "Consequence",
          "type": "dropdown",
          "label in bubble": "true"
        }
      ],
      "visualizer": {
        "type": "region plot",
        "x axis field": "position",
        "y axis field": "-log10(P-Value)",
        "render by": "Variant ID",
        "y axis label": "-Log10(p-value)",
        "x axis label": "Chromosome",
        "hover content": [
          "P-Value",
          "Beta"
        ],
        "height": 120,
        "ld server": {
          "pos": "position",
          "ref": "ref",
          "alt": "alt",
          "ref variant field": "Variant ID",
          "populations field": "P-Value",
          "populations type": "fixed",
          "fixed population": "ALL",
          "populations": {
            "ALL": "ALL"
          }
        },
        "genes track": {
          "input type": "dynamic",
          "dynamic parameter": "region"
        },
        "input type": "dynamic",
        "dynamic parameter": "region",
        "if combine y axis field": {
          "type": "average",
          "field": "-log10(P-Value)"
        }
      }
    }
  ]
}
